sections.description:
Library Name: QMI8658A

Include Syntax:
#include <QMI8658A.h>

examples:
#include <Arduino.h>
#include <QMI8658A.h>

#define IMU_SDA 48
#define IMU_SCL 47

QMI8658A imu;

void setup() {
  Serial.begin(115200);

  if (!imu.begin(&Wire, IMU_SDA, IMU_SCL)) {
    Serial.println("IMU init failed!");
    while (1);
  }
}

void loop() {
  float ax, ay, az, gx, gy, gz, temp;

  if (imu.readAll(ax, ay, az, gx, gy, gz, temp)) {
    Serial.print("ACC X: "); Serial.print(ax);
    Serial.print(" Y: "); Serial.print(ay);
    Serial.print(" Z: "); Serial.print(az);

    Serial.print(" | GYR X: "); Serial.print(gx);
    Serial.print(" Y: "); Serial.print(gy);
    Serial.print(" Z: "); Serial.println(gz);

    Serial.print("TEMP: "); Serial.println(temp);
  }

  delay(300);
}

