Initializes the SD card and I2S audio output.

examples:
#include <Arduino.h>
#include "FS.h"
#include "SD_MMC.h"
#include "AudioGeneratorMP3.h"
#include "AudioFileSourceFS.h"
#include "AudioOutputI2S.h"

#define I2S_BCLK 41
#define I2S_DOUT 42
#define I2S_LRCLK 43

AudioGeneratorMP3 *mp3;
AudioFileSourceFS *file;
AudioOutputI2S *out;

void setup() {
  Serial.begin(115200);

  SD_MMC.setPins(39, 38, 40);
  if (!SD_MMC.begin("/sdcard", true)) {
    Serial.println("SD mount failed");
    return;
  }

  out = new AudioOutputI2S();
  out->SetPinout(I2S_BCLK, I2S_LRCLK, I2S_DOUT);
  out->SetGain(1.0);

  file = new AudioFileSourceFS(SD_MMC, "/new.mp3");
  mp3 = new AudioGeneratorMP3();

  mp3->begin(file, out);
}

void loop() {
  if (mp3->isRunning()) {
    mp3->loop();
  }
}

sections.description:
Create a servo object and attach it to a pin in the setup() function:

Servo myServo;
myServo.attach(SERVO_PIN, 500, 2400);

Control the servo angle inside the loop() function using:

myServo.write(angle);

examples:
#include <ESP32Servo.h>

Servo myServo;

#define SERVO_PIN 1

void setup() {
  myServo.attach(SERVO_PIN, 500, 2400);
}

void loop() {
  myServo.write(90);  // Rotate to 90 degrees
  delay(1000);

  myServo.write(0);   // Rotate back to 0 degrees
  delay(1000);
}

