1. Library Name: Arduino

2. Include Syntax:
#include <Arduino.h>

examples:
#include <Arduino.h>

#define SERIAL_SERVO_RX 1
#define SERIAL_SERVO_TX 2
#define BAUDRATE 115200

uint8_t DsCheckSum(uint8_t buf[], uint8_t len) {
  uint16_t temp = 0;
  for (uint8_t i = 2; i < len - 1; i++) temp += buf[i];
  temp = temp & 0xFF;
  temp = ~temp;
  return (uint8_t)temp;
}

void serialServo_config() {
  Serial1.begin(BAUDRATE, SERIAL_8N1, SERIAL_SERVO_RX, SERIAL_SERVO_TX);
  delay(50);
}

void DS_ServoMove(uint8_t id, int16_t position, uint16_t time) {
  uint8_t buf[11] = {
    0xFF, 0xFF, id, 0x07, 0x03, 0x2A,
    (uint8_t)(position >> 8), (uint8_t)(position & 0xFF),
    (uint8_t)(time >> 8), (uint8_t)(time & 0xFF), 0x00
  };
  buf[10] = DsCheckSum(buf, sizeof(buf));
  Serial1.write(buf, sizeof(buf));
}

void setup() {
  Serial.begin(115200);
  serialServo_config();
}

void loop() {
  DS_ServoMove(7, 500, 1000); // move servo ~90°
  delay(2000);

  DS_ServoMove(7, 900, 1000); // move servo near 180°
  delay(2000);
}

uint8_t DsCheckSum(uint8_t buf[], uint8_t len) {
  uint16_t temp = 0;
  for (uint8_t i = 2; i < len - 1; i++) temp += buf[i];
  temp = temp & 0xFF;
  temp = ~temp;
  return (uint8_t)temp;
}

void serialServo_config() {
  Serial1.begin(115200, SERIAL_8N1, 1, 2);
  delay(50);
}

// === Read Servo Position ===
int DsServoReadPosition(uint8_t id) {
  uint8_t buf[8] = {0xFF, 0xFF, id, 0x04, 0x02, 0x38, 0x02, 0x00};
  buf[7] = DsCheckSum(buf, sizeof(buf));
  Serial1.write(buf, sizeof(buf));
  delay(20);

  if (Serial1.available() >= 8) {
    uint8_t resp[16];
    int len = Serial1.readBytes(resp, sizeof(resp));

    if (len >= 8) {
      int rawPos = (resp[len - 3] << 8) | resp[len - 2];
      int degrees = map(rawPos, 0, 1000, 0, 180);
      return degrees;
    }
  }
  return -1;
}

// ================= MAIN =================
void setup() {
  Serial.begin(115200);
  serialServo_config();
  Serial.println("Servo ID=4 position monitor...");}

void loop() {
  int pos = DsServoReadPosition(4);
  if (pos >= 0) {
   Serial.println("Servo Angle3: " + String(pos));
  }
else {
    Serial.println("Failed to read position");
 }
  delay(200);
}
